state-layout.extra_styles:
@keyframes fx-spin { to { transform: translate(-50%,-50%) rotate(360deg); } }
@keyframes fx-glow-mono { 0%,100% { box-shadow: 0 0 5px 0 var(--fx-glow-color, transparent); } 50% { box-shadow: 0 0 18px 4px var(--fx-glow-color, transparent); } }
@keyframes fx-glow-rainbow {
  0%{box-shadow:0 0 16px 4px var(--battman-red);}16%{box-shadow:0 0 16px 4px var(--battman-orange);}
  33%{box-shadow:0 0 16px 4px var(--battman-yellow);}50%{box-shadow:0 0 16px 4px var(--battman-green);}
  66%{box-shadow:0 0 16px 4px var(--battman-blue);}83%{box-shadow:0 0 16px 4px var(--battman-purple);}
  100%{box-shadow:0 0 16px 4px var(--battman-red);}
}
ha-card { overflow: visible !important; }
/* bottom pill — same fx harness as the mode buttons; the chase spins a conic layer behind a centre mask */
.fxp { overflow: hidden; }
.fxp::before {
  content:''; position:absolute; z-index:0; top:50%; left:50%; width:600px; height:600px; transform: translate(-50%,-50%);
  background: var(--fx-chase-gradient, none); animation: fx-spin var(--fx-chase-duration, 0s) linear infinite; display: var(--fx-ring, none);
}
.fxp::after {
  content:''; position:absolute; z-index:1; inset: var(--fx-ring-width, 2px); border-radius:999px;
  background: var(--battman-surface-popup); display: var(--fx-ring, none);
}
.fxp > * { position: relative; z-index: 2; }
@media (prefers-reduced-motion: reduce) { .fxp, .fxp::before { animation: none !important; } }
